import{_ as t,o as a,c as r,au as n,aR as o,aS as s}from"./chunks/framework.BKE8ybUb.js";import"./chunks/theme.XLLNTsgn.js";const _=JSON.parse('{"title":"Frozen","description":"","frontmatter":{"outline":[1,2],"prev":{"text":"Elemental Reactions","link":"/guide/elements/Elemental_Reactions"}},"headers":[],"relativePath":"Frozen.md","filePath":"wiki/elemental_reactions/Frozen.md","lastUpdated":1783267680000}'),i={name:"Frozen.md"};function l(g,e,c,p,h,d){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="Frozen" tabindex="-1">Frozen <a class="header-anchor" href="#Frozen" aria-label="Permalink to “Frozen”">​</a></h1><p>Frozen is the <a href="./guide/elements/Elemental_Reactions">Elemental Reaction</a> triggered when <span class="cryo"><strong>Cryo</strong></span> is applied onto an entity already affected by <span class="hydro"><strong>Hydro</strong></span> or vice versa.</p><p>Frozen by itself deals <strong>no damage</strong>. Instead, it applies a <span class="cryo"><strong>Freeze</strong></span> aura and the &quot;Frozen&quot; Status Effect onto the target for a certain period of time.</p><p>While the &quot;Frozen&quot; Status Effect is active, the entity cannot place or break blocks, move normally, attack, or use (right-click) items.</p><p>When an entity with the <span class="cryo"><strong>Freeze</strong></span> aura receives <span class="geo"><strong>Geo DMG</strong></span> or is hit by a <a href="./Item_tag#heavy_weapon">Heavy Weapon</a>, the <a href="#Shatter"><strong>Shatter</strong></a> reaction is triggered.</p><p>Inflicting <span class="pyro"><strong>Pyro</strong></span>/<span class="electro"><strong>Electro</strong></span>/<span class="hydro"><strong>Anemo</strong></span> on a Freeze aura will consume it to trigger <a href="./Melt">Melt</a>/<a href="./Superconduct">Superconduct</a>/<a href="./Swirl">Swirl</a> respectively.</p><div align="center"><video width="95%" height="auto" controls><source src="'+o+'" type="video/mp4"> Your browser does not support the video tag. </video></div><h3 id="Internal_Data" tabindex="-1">Internal Data <a class="header-anchor" href="#Internal_Data" aria-label="Permalink to “Internal Data”">​</a></h3><p>Reaction ID: <code>seven-elements:frozen</code></p><div><br></div><hr><h1 id="Shatter" tabindex="-1">Shatter <a class="header-anchor" href="#Shatter" aria-label="Permalink to “Shatter”">​</a></h1><p>Shatter is the <a href="./guide/elements/Elemental_Reactions">Elemental Reaction</a> triggered when an entity inflicted with the <span class="cryo"><strong>Freeze</strong></span> aura receives <span class="geo"><strong>Geo DMG</strong></span> or is <strong>directly</strong> hit by a <a href="./Item_tag#heavy_weapon">Heavy Weapon</a>.</p><p>Shatter <strong>cannot</strong> be triggered directly on the same hit after a <span class="cryo"><strong>Frozen</strong></span> reaction even when it was triggered by a <strong>direct</strong> hit from a <a href="./Item_tag#heavy_weapon">Heavy Weapon</a>. Shatter can <strong>only</strong> be triggered by a <strong>direct</strong> hit from a <a href="./Item_tag#heavy_weapon">Heavy Weapon</a> that does <strong>not</strong> trigger the <span class="cryo"><strong>Frozen</strong></span> reaction on the same hit.</p><p>Upon triggering Shatter, the <span class="cryo"><strong>Freeze</strong></span> aura is removed. If Shatter was triggered by dealing <span class="geo"><strong>Geo DMG</strong></span>, the <span class="geo"><strong>Geo</strong></span> attack that dealt the damage will sustain no gauge deduction.</p><p>Unlike <strong>Genshin Impact</strong>, Shatter has its own <em>reaction text</em>!</p><div align="center"><video width="95%" height="auto" controls><source src="'+s+'" type="video/mp4"> Your browser does not support the video tag. </video></div><h3 id="Internal_Data-1" tabindex="-1">Internal Data <a class="header-anchor" href="#Internal_Data-1" aria-label="Permalink to “Internal Data”">​</a></h3><p>Reaction Multiplier: <strong>3</strong><br> Reaction ID(s):</p><ul><li><code>seven-elements:shatter_heavy</code> (triggered by being hit with a <a href="./Item_tag#heavy_weapon">Heavy Weapon</a>)</li><li><code>seven-elements:shatter_geo</code> (triggered by receiving <span class="geo"><strong>Geo DMG</strong></span>)</li></ul>',20)])])}const u=t(i,[["render",l]]);export{_ as __pageData,u as default};
